from flask import Flask, request, jsonify, Blueprint

app = Flask(__name__)

# (1) ROUTING: a decorator maps a URL to a view function.
@app.route('/hello/<name>')
def hello(name):
    return f'Hello, {name}!'            # a string -> a response

# (2) REQUEST/RESPONSE: the request object carries input; jsonify -> JSON.
@app.route('/api/items', methods=['POST'])
def create_item():
    data = request.get_json()           # parse the JSON body
    #   ... validate and save (you choose the ORM: SQLAlchemy, etc.) ...
    return jsonify({'status': 'created', 'item': data}), 201

# (3) BLUEPRINT: group related views for a larger app (modular).
admin_bp = Blueprint('admin', __name__, url_prefix='/admin')
@admin_bp.route('/dashboard')
def dashboard():
    return 'Admin dashboard'
app.register_blueprint(admin_bp)
#   Flask gives you ROUTING + REQUEST/RESPONSE + BLUEPRINTS. The ORM, auth,
#   and forms you CHOOSE (SQLAlchemy, Flask-Login, WTForms) and wire.
